                return (
                  <label key={id} className={`pl-choice ${level === id ? 'is-on' : ''}`}>
                    <input type="radio" name={`start-${tc.key}`} checked={level === id} onChange={() => pickLevel(tc.key, id)} />
                    <span>
                      <b>{words.short}</b>
                      {id === RECOMMENDED && <span className="pl-tag">Recommended</span>}
